// Absolute accepts, a both-lane band near the lane leader, and a dated
// generic-schedule cosine floor. Defaults keep absolute rejection:
// omitted floors equal the accepts and omitted gaps are zero.
const cosAccept = filter?.minCosine ?? -1;
const ftsAccept = filter?.minFtsScore ?? 0;
const cosFloor = filter?.cosineFloor ?? cosAccept;
const ftsFloor = filter?.ftsFloor ?? ftsAccept;
const cosGap = filter?.cosineGap ?? 0;
const ftsGap = filter?.ftsGap ?? 0;
const dateFloor = filter?.genericSchedule ? (filter?.dateCosineFloor ?? cosFloor) : cosAccept;
const cosIds = new Map(vecRaw.map(r => [r.record_id, r.score]));
const ftsIds = new Map(ftsRaw.map(r => [r.record_id, r.score]));
const bestCos = Math.max(-1, ...cosIds.values());
const bestFts = Math.max(-1, ...ftsIds.values());
const supported = new Set();
for (const [id, cos] of cosIds) {
  const lex = ftsIds.get(id);
  if (lex === undefined) continue;
  if (cos >= cosFloor && lex >= ftsFloor && bestCos - cos <= cosGap && bestFts - lex <= ftsGap) supported.add(id);
}
const ftsHits = ftsRaw.filter(r => r.score >= ftsAccept || supported.has(r.record_id)).map(r => ({ ...r, ftsScore: r.score }));
const vecHits = vecRaw.filter(r => r.score >= cosAccept || (filter?.genericSchedule && r.score >= dateFloor) || supported.has(r.record_id)).map(r => ({ ...r, cosine: r.score }));
const ftsOk = Boolean(ftsHits.length);

  metadata_json: r.metadata_json,
  ...((r as any).ftsRank !== undefined ? { ftsRank: (r as any).ftsRank } : {}),
};
